{
  "candidate": {
    "version": 1,
    "source_tool": "point_in_polygon_tool",
    "target": {
      "kind": "single",
      "tool": "points_within_polygon_tool"
    },
    "steps": [
      {
        "op": "RenameTool",
        "from": "point_in_polygon_tool",
        "to": "points_within_polygon_tool",
        "evidence": [
          "change-evidence.md#historical-change"
        ]
      },
      {
        "op": "WrapArray",
        "source": "point",
        "target": "points",
        "evidence": [
          "change-evidence.md#historical-change"
        ]
      }
    ],
    "response": [
      {
        "op": "ConstructResponse",
        "fields": [
          {
            "name": "inside",
            "binding": {
              "kind": "compareInteger",
              "source": {
                "kind": "response",
                "path": "count"
              },
              "operator": "gt",
              "value": 0
            }
          },
          {
            "name": "point",
            "binding": {
              "kind": "input",
              "path": "point"
            }
          }
        ],
        "evidence": [
          "change-evidence.md#historical-change"
        ]
      }
    ],
    "rationale": "Migrates point_in_polygon_tool to points_within_polygon_tool by wrapping the single point input into an array for the points parameter and constructing the response with inside mapped to count > 0 and preserving the original input point."
  }
}
